package com.bank.processing.batch;

import com.bank.processing.model.Transaction;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// BATCH: sees the whole bounded dataset and aggregates it in one run.
public class BatchProcessor {
    private static final Logger log = Logger.getLogger(BatchProcessor.class.getName());

    public Map<String, BigDecimal> runEndOfDay(List<Transaction> dayTransactions) {
        log.info(() -> "BATCH end-of-day run over " + dayTransactions.size() + " transactions");
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (Transaction t : dayTransactions) {
            totals.merge(t.getAccountId(), t.getAmount(), BigDecimal::add);
        }
        return totals;
    }
}
