package com.bank.processing.stream;

import com.bank.processing.model.Transaction;
import java.math.BigDecimal;
import java.util.logging.Logger;

// STREAM: processes ONE event the instant it arrives; raises alerts immediately.
public class StreamProcessor {
    private static final Logger log = Logger.getLogger(StreamProcessor.class.getName());
    private final BigDecimal alertThreshold;

    public StreamProcessor(BigDecimal alertThreshold) { this.alertThreshold = alertThreshold; }

    public void onEvent(Transaction t) {
        log.fine(() -> "STREAM received " + t.getTxnId() + " at " + t.getEventTime());
        if (t.getAmount().compareTo(alertThreshold) > 0) {
            log.severe(() -> "FRAUD ALERT: " + t.getAccountId() + " spent " + t.getAmount()
                    + " (> " + alertThreshold + ") at " + t.getEventTime());
        } else {
            log.info(() -> "OK: " + t.getAccountId() + " spent " + t.getAmount());
        }
    }
}
