package com.bank.processing;

import com.bank.processing.batch.BatchProcessor;
import com.bank.processing.model.Transaction;
import com.bank.processing.stream.StreamProcessor;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.logging.Logger;

public class ProcessingDemo {
    private static final Logger log = Logger.getLogger(ProcessingDemo.class.getName());

    public static void main(String[] args) {
        LocalDateTime now = LocalDateTime.of(2024, 10, 29, 10, 0);
        List<Transaction> txns = List.of(
            new Transaction("T1", "SAV2001", new BigDecimal("1200.00"), now),
            new Transaction("T2", "SAV2001", new BigDecimal("150000.00"), now.plusMinutes(1)),
            new Transaction("T3", "CUR3001", new BigDecimal("5000.00"), now.plusMinutes(2)),
            new Transaction("T4", "CUR3001", new BigDecimal("250000.00"), now.plusMinutes(3)),
            new Transaction("T5", "SAV2001", new BigDecimal("800.00"), now.plusMinutes(4))
        );

        log.info("--- STREAM MODE (immediate, per event) ---");
        StreamProcessor stream = new StreamProcessor(new BigDecimal("100000.00"));
        txns.forEach(stream::onEvent);

        log.info("--- BATCH MODE (end of day, whole pile) ---");
        BatchProcessor batch = new BatchProcessor();
        batch.runEndOfDay(txns).forEach((acc, total) ->
            log.info("ACCOUNT " + acc + " total=" + total));
    }
}
